#include <zephyr/ztest.h>
#include <zephyr/net/buf.h>
#include <zephyr/kernel.h>
#include <string.h>

#define TEST_BUF_SIZE 64
#define TEST_BUF_COUNT 4
#define TEST_DATA_LEN 16

NET_BUF_POOL_DEFINE(test_pool, TEST_BUF_COUNT, TEST_BUF_SIZE, 0, NULL);

static void *net_buf_setup(void)
{
    return NULL;
}

static void net_buf_teardown(void *fixture)
{
    struct net_buf *buf;
    int count = 0;
    while ((buf = net_buf_alloc(&test_pool, K_NO_WAIT)) != NULL) {
        net_buf_destroy(buf);
        count++;
    }
    zassert_equal(count, TEST_BUF_COUNT, "Not all buffers returned to pool in teardown");
}

/* Test case 1: Basic allocation and destruction */
ZTEST(net_buf_tests, test_alloc_destroy)
{
    struct net_buf *buf;
    int i;

    for (i = 0; i < TEST_BUF_COUNT; i++) {
        buf = net_buf_alloc(&test_pool, K_NO_WAIT);
        zassert_not_null(buf, "Failed to allocate buffer %d", i);
        zassert_equal(net_buf_tailroom(buf), TEST_BUF_SIZE, "Incorrect tailroom after alloc");
        zassert_equal(net_buf_headroom(buf), 0, "Incorrect headroom after alloc");
        zassert_equal(net_buf_frags(buf), NULL, "Fragments not NULL after alloc");
        zassert_equal(net_buf_len(buf), 0, "Length not 0 after alloc");
        net_buf_destroy(buf);
    }

    buf = net_buf_alloc(&test_pool, K_NO_WAIT);
    zassert_is_null(buf, "Allocated buffer beyond pool capacity");

    zassert_equal(test_pool.avail_count, TEST_BUF_COUNT, "Pool count not restored after alloc/destroy cycle");
}

/* Test case 2: Adding and pulling data with various types and detailed checks */
ZTEST(net_buf_tests, test_add_pull_data_types)
{
    struct net_buf *buf;
    uint8_t u8_val = 0xAA;
    uint16_t u16_val = 0xCCDD;
    uint32_t u32_val = 0x11223344;
    uint8_t data[TEST_DATA_LEN];
    uint8_t read_data[TEST_DATA_LEN];
    uint8_t read_u8;
    uint16_t read_u16;
    uint32_t read_u32;
    uint8_t *ptr;
    size_t len;

    memset(data, 0x55, sizeof(data));

    buf = net_buf_alloc(&test_pool, K_NO_WAIT);
    zassert_not_null(buf, "Failed to allocate buffer");

    /* Add data */
    net_buf_add_u8(buf, u8_val);
    net_buf_add_le16(buf, u16_val);
    net_buf_add_be32(buf, u32_val);
    net_buf_add_mem(buf, data, sizeof(data));

    len = 1 + 2 + 4 + TEST_DATA_LEN;
    zassert_equal(net_buf_len(buf), len, "Incorrect length after adds");
    zassert_equal(net_buf_tailroom(buf), TEST_BUF_SIZE - len, "Incorrect tailroom after adds");

    /* Check data pointers */
    ptr = net_buf_head(buf);
    zassert_equal(*ptr, u8_val, "Head data mismatch (u8)");
    ptr = net_buf_tail(buf);
    zassert_equal(*(ptr - 1), data[TEST_DATA_LEN - 1], "Tail data mismatch (mem)");
    zassert_equal(net_buf_data(buf), net_buf_head(buf), "net_buf_data should be net_buf_head initially");

    /* Pull data */
    read_u8 = net_buf_pull_u8(buf);
    zassert_equal(read_u8, u8_val, "Pulled u8 mismatch");
    zassert_equal(net_buf_len(buf), len - 1, "Length after pull u8 incorrect");
    zassert_equal(net_buf_data(buf), net_buf_head(buf) + 1, "net_buf_data not advanced after pull u8");

    read_u16 = net_buf_pull_le16(buf);
    zassert_equal(read_u16, u16_val, "Pulled le16 mismatch");
    zassert_equal(net_buf_len(buf), len - 1 - 2, "Length after pull le16 incorrect");
    zassert_equal(net_buf_data(buf), net_buf_head(buf) + 1 + 2, "net_buf_data not advanced after pull le16");

    read_u32 = net_buf_pull_be32(buf);
    zassert_equal(read_u32, u32_val, "Pulled be32 mismatch");
    zassert_equal(net_buf_len(buf), len - 1 - 2 - 4, "Length after pull be32 incorrect");
    zassert_equal(net_buf_data(buf), net_buf_head(buf) + 1 + 2 + 4, "net_buf_data not advanced after pull be32");

    net_buf_pull_mem(buf, read_data, sizeof(read_data));
    zassert_mem_equal(data, read_data, sizeof(data), "Pulled mem mismatch");
    zassert_equal(net_buf_len(buf), 0, "Buffer not empty after all pulls");
    zassert_equal(net_buf_data(buf), net_buf_head(buf) + len, "net_buf_data not at end after all pulls");

    /* The following line was originally 'net_buf_destory(buf);' causing the error. */
    net_buf_destroy(buf);
}

/* Test case 3: Headroom and tailroom manipulation */
ZTEST(net_buf_tests, test_headroom_tailroom)
{
    struct net_buf *buf;
    uint8_t data[] = {0xAA, 0xBB};

    buf = net_buf_alloc(&test_pool, K_NO_WAIT);
    zassert_not_null(buf, "Failed to allocate buffer");

    net_buf_reserve(buf, 10);
    zassert_equal(net_buf_headroom(buf), 10, "Incorrect headroom after reserve");
    zassert_equal(net_buf_tailroom(buf), TEST_BUF_SIZE - 10, "Incorrect tailroom after reserve");

    net_buf_add_mem(buf, data, sizeof(data));
    zassert_equal(net_buf_len(buf), sizeof(data), "Incorrect length after add");
    zassert_equal(net_buf_headroom(buf), 10, "Headroom changed unexpectedly");
    zassert_equal(net_buf_tailroom(buf), TEST_BUF_SIZE - 10 - sizeof(data), "Incorrect tailroom");

    net_buf_pull(buf, 1); /* Pull 1 byte */
    zassert_equal(net_buf_len(buf), 1, "Incorrect length after pull");
    zassert_equal(net_buf_headroom(buf), 11, "Headroom not increased after pull");

    net_buf_destroy(buf);
}

/* Test case 4: Fragment handling (simple case) */
ZTEST(net_buf_tests, test_fragments_simple)
{
    struct net_buf *buf1, *buf2;
    uint8_t data1[] = {0x11, 0x22};
    uint8_t data2[] = {0x33, 0x44};

    buf1 = net_buf_alloc(&test_pool, K_NO_WAIT);
    zassert_not_null(buf1, "Failed to allocate buf1");
    net_buf_add_mem(buf1, data1, sizeof(data1));

    buf2 = net_buf_alloc(&test_pool, K_NO_WAIT);
    zassert_not_null(buf2, "Failed to allocate buf2");
    net_buf_add_mem(buf2, data2, sizeof(data2));

    net_buf_frag_add(buf1, buf2);
    zassert_equal(net_buf_frags(buf1), buf2, "Fragment not added");
    zassert_equal(net_buf_frags(buf2), NULL, "Fragment has unexpected next");

    net_buf_destroy(buf1); /* This should destroy buf1 and then buf2 */
}

/* Test case 5: Test net_buf_unref */
ZTEST(net_buf_tests, test_unref)
{
    struct net_buf *buf;

    buf = net_buf_alloc(&test_pool, K_NO_WAIT);
    zassert_not_null(buf, "Failed to allocate buffer");

    /* Initial ref count is 1 */
    zassert_equal(buf->ref, 1, "Initial ref count not 1");

    net_buf_ref(buf); /* Increment ref count */
    zassert_equal(buf->ref, 2, "Ref count not 2 after ref");

    net_buf_unref(buf); /* Decrement ref count */
    zassert_equal(buf->ref, 1, "Ref count not 1 after unref");

    net_buf_unref(buf); /* Decrement ref count, should destroy */
    /* At this point, buf is destroyed and returned to pool.
     * We cannot access buf->ref anymore.
     * We can check pool count.
     */
    zassert_equal(test_pool.avail_count, TEST_BUF_COUNT, "Buffer not returned to pool after final unref");

    /* Try to allocate again to confirm it's back */
    buf = net_buf_alloc(&test_pool, K_NO_WAIT);
    zassert_not_null(buf, "Failed to re-allocate buffer after unref");
    net_buf_destroy(buf); /* Clean up */
}

/* Test case 6: Test net_buf_linearize */
ZTEST(net_buf_tests, test_linearize)
{
    struct net_buf *buf_frag1, *buf_frag2, *buf_linear;
    uint8_t data1[] = {0x01, 0x02, 0x03, 0x04};
    uint8_t data2[] = {0x05, 0x06, 0x07, 0x08};
    uint8_t expected_data[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08};
    uint8_t read_data[sizeof(expected_data)];
    size_t len;

    buf_frag1 = net_buf_alloc(&test_pool, K_NO_WAIT);
    zassert_not_null(buf_frag1, "Failed to allocate buf_frag1");
    net_buf_add_mem(buf_frag1, data1, sizeof(data1));

    buf_frag2 = net_buf_alloc(&test_pool, K_NO_WAIT);
    zassert_not_null(buf_frag2, "Failed to allocate buf_frag2");
    net_buf_add_mem(buf_frag2, data2, sizeof(data2));

    net_buf_frag_add(buf_frag1, buf_frag2);

    buf_linear = net_buf_alloc(&test_pool, K_NO_WAIT);
    zassert_not_null(buf_linear, "Failed to allocate buf_linear");

    len = net_buf_linearize(buf_linear, buf_frag1, 0, sizeof(expected_data));
    zassert_equal(len, sizeof(expected_data), "Incorrect linearized length");
    zassert_equal(net_buf_len(buf_linear), sizeof(expected_data), "Linearized buffer has incorrect length");

    net_buf_pull_mem(buf_linear, read_data, sizeof(read_data));
    zassert_mem_equal(expected_data, read_data, sizeof(expected_data), "Linearized data mismatch");

    net_buf_destroy(buf_linear);
    net_buf_destroy(buf_frag1); /* This will also destroy buf_frag2 */
}

ZTEST_SUITE(net_buf_tests, net_buf_setup, net_buf_teardown, NULL, NULL, NULL);
